            for j in range(m):
                if i != j:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiplication(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def log2(x):
        if x <= 0:
            return float('-inf')
        return math.log2(x)

    n = random.randint(5, 40)
    P = [[random.choice([0, 1]) for _ in range(n)] for _ in range(n)]

